#!/usr/bin/env python3
"""Packs Joe and Kuo's Sobol' direction numbers into sobol_directions.inc.

cuRAND documents its Sobol' direction vectors as generated from the
polynomials S. Joe and F. Y. Kuo recommend, for 20,000 dimensions
(CURAND_DIRECTION_VECTORS_32_JOEKUO6 and _64_JOEKUO6). This reads their
published file, new-joe-kuo-6.21201, from

    https://web.maths.unsw.edu.au/~fkuo/sobol/new-joe-kuo-6.21201

and writes the first 20,000 dimensions' parameters as one bitstream, base64
encoded. For each dimension from 2 on: the polynomial's degree s (5 bits), its
interior coefficients a (s - 1 bits), and each initial direction number m_k,
k = 1..s, which is odd and below 2^k, as (m_k - 1) / 2 in k - 1 bits. The
first dimension has no parameters: its vectors are 1 << (bits - 1 - i).

    gen_sobol_directions.py new-joe-kuo-6.21201 > sobol_directions.inc
"""
import base64
import sys

DIMS = 20000
LICENCE = """\
Copyright (c) 2008, Frances Y. Kuo and Stephen Joe
All rights reserved.

Redistribution and use in source and binary forms, with or without
modification, are permitted provided that the following conditions are met:

    * Redistributions of source code must retain the above copyright
      notice, this list of conditions and the following disclaimer.

    * Redistributions in binary form must reproduce the above copyright
      notice, this list of conditions and the following disclaimer in the
      documentation and/or other materials provided with the distribution.

    * Neither the names of the copyright holders nor the names of the
      University of New South Wales and the University of Waikato
      and its contributors may be used to endorse or promote products derived
      from this software without specific prior written permission.

THIS SOFTWARE IS PROVIDED BY THE COPYRIGHT HOLDERS ``AS IS'' AND ANY
EXPRESS OR IMPLIED WARRANTIES, INCLUDING, BUT NOT LIMITED TO, THE IMPLIED
WARRANTIES OF MERCHANTABILITY AND FITNESS FOR A PARTICULAR PURPOSE ARE
DISCLAIMED. IN NO EVENT SHALL THE COPYRIGHT HOLDERS BE LIABLE FOR ANY
DIRECT, INDIRECT, INCIDENTAL, SPECIAL, EXEMPLARY, OR CONSEQUENTIAL DAMAGES
(INCLUDING, BUT NOT LIMITED TO, PROCUREMENT OF SUBSTITUTE GOODS OR SERVICES;
LOSS OF USE, DATA, OR PROFITS; OR BUSINESS INTERRUPTION) HOWEVER CAUSED AND
ON ANY THEORY OF LIABILITY, WHETHER IN CONTRACT, STRICT LIABILITY, OR TORT
(INCLUDING NEGLIGENCE OR OTHERWISE) ARISING IN ANY WAY OUT OF THE USE OF THIS
SOFTWARE, EVEN IF ADVISED OF THE POSSIBILITY OF SUCH DAMAGE.
"""


class Bits:
    def __init__(self):
        self.out = bytearray()
        self.acc = 0
        self.n = 0

    def put(self, value, width):
        # Most significant bit first.
        for i in range(width - 1, -1, -1):
            self.acc = (self.acc << 1) | ((value >> i) & 1)
            self.n += 1
            if self.n == 8:
                self.out.append(self.acc)
                self.acc = self.n = 0

    def done(self):
        if self.n:
            self.out.append(self.acc << (8 - self.n))
        return bytes(self.out)


def main():
    rows = []
    with open(sys.argv[1]) as f:
        next(f)  # the column header
        for line in f:
            parts = line.split()
            if not parts:
                continue
            d, s, a = int(parts[0]), int(parts[1]), int(parts[2])
            m = [int(x) for x in parts[3:]]
            if d > DIMS:
                break
            assert len(m) == s and s < 32 and a < (1 << max(s - 1, 0))
            assert all(v % 2 == 1 and v < (1 << (k + 1)) for k, v in enumerate(m))
            rows.append((s, a, m))
    assert len(rows) == DIMS - 1
    bits = Bits()
    for s, a, m in rows:
        bits.put(s, 5)
        bits.put(a, s - 1)
        for k, v in enumerate(m, start=1):
            bits.put((v - 1) // 2, k - 1)
    text = base64.b64encode(bits.done()).decode()
    print("// GENERATED by gen_sobol_directions.py from Joe and Kuo's new-joe-kuo-6.21201:")
    print("// the Sobol' direction number parameters of dimensions 2 to %d, packed as" % DIMS)
    print("// that script describes. Their licence:")
    print("//")
    for line in LICENCE.splitlines():
        print(("// " + line).rstrip())
    print("static const char kSobolJoeKuo[] =")
    for i in range(0, len(text), 96):
        print('    "%s"' % text[i:i + 96])
    print("    ;")


if __name__ == "__main__":
    main()
